1	// Red-first fixture tests for the gcec pack's checks, runnable by this repo's own
2	// `npm test` (no imports from the gitignored .claudinite mount — see the check
3	// module's header). Each rule is shown firing on a violating fixture and staying
4	// quiet on a clean one.
5	import test from 'node:test';
6	import assert from 'node:assert/strict';
7	import testOfflineListSync from './test-offline-list-sync.mjs';
8	import customSourcesFlat from './custom-sources-flat.mjs';
9	import npmTestGlobCoverage from './npm-test-glob-coverage.mjs';
10	
11	function ctx({ files = [], pkg }) {
12	  const disk = new Set([...files, 'package.json']);
13	  return {
14	    files,
15	    read: (p) => (p === 'package.json' ? JSON.stringify(pkg) : null),
16	    exists: (p) => disk.has(p),
17	  };
18	}
19	
20	const pkgWith = (offline) => ({ scripts: { 'test:offline': `node --test ${offline.join(' ')}` } });
21	
22	test('test-offline-list-sync: fires when a mirror test is missing from the list', () => {
23	  const findings = testOfflineListSync.run(
24	    ctx({
25	      files: ['extension-test/a.test.js', 'extension-test/b.test.js'],
26	      pkg: pkgWith(['extension-test/a.test.js']),
27	    }),
28	  );
29	  assert.equal(findings.length, 1);
30	  assert.match(findings[0].what, /missing extension-test\/b\.test\.js/);
31	  assert.equal(findings[0].severity, 'blocking');
32	});
33	
34	test('test-offline-list-sync: fires when the list names a file that does not exist', () => {
35	  const findings = testOfflineListSync.run(
36	    ctx({
37	      files: ['extension-test/a.test.js'],
38	      pkg: pkgWith(['extension-test/a.test.js', 'extension-test/gone.test.js']),
39	    }),
40	  );
41	  assert.equal(findings.length, 1);
42	  assert.match(findings[0].what, /extension-test\/gone\.test\.js, which does not exist/);
43	});
44	
45	test('test-offline-list-sync: quiet when list and tree agree (non-mirror entries ignored)', () => {
46	  const findings = testOfflineListSync.run(
47	    ctx({
48	      files: ['extension-test/a.test.js', 'dev/build/test/other.test.js'],
49	      pkg: pkgWith(['extension-test/a.test.js', 'dev/build/release/shipping-files.test.js']),
50	    }),
51	  );
52	  assert.deepEqual(findings, []);
53	});
54	
55	test('test-offline-list-sync: quiet when package.json has no test:offline script', () => {
56	  const findings = testOfflineListSync.run(
57	    ctx({ files: ['extension-test/a.test.js'], pkg: { scripts: {} } }),
58	  );
59	  assert.deepEqual(findings, []);
60	});
61	
62	// A context whose files ARE the keys of a path → content map, for the rules that
63	// read file text rather than package.json.
64	const treeCtx = (tree) => ({
65	  files: Object.keys(tree),
66	  read: (p) => (p in tree ? tree[p] : null),
67	  exists: (p) => p in tree,
68	});
69	
70	test('custom-sources-flat: fires on a subdirectory, a non-source file, and a pipeline file in custom/', () => {
71	  const findings = customSourcesFlat.run(
72	    treeCtx({
73	      'extension/event-extractors/custom/barby.js': '',
74	      'extension/event-extractors/custom/shared/util.js': '',
75	      'extension/event-extractors/custom/README.md': '',
76	      'extension/event-extractors/custom/generic-extractor.js': '',
77	    }),
78	  );
79	  assert.equal(findings.length, 3);
80	  assert.match(findings[0].what, /sits in a subdirectory/);
81	  assert.match(findings[1].what, /is not a per-site source/);
82	  assert.match(findings[2].what, /is a pipeline file/);
83	  assert.ok(findings.every((f) => f.severity === 'blocking'));
84	});
85	
86	test('custom-sources-flat: quiet on a flat tree of per-site sources beside the pipeline', () => {
87	  const findings = customSourcesFlat.run(
88	    treeCtx({
89	      'extension/event-extractors/custom/barby.js': '',
90	      'extension/event-extractors/custom/tel-aviv.js': '',
91	      'extension/event-extractors/generic-extractor.js': '',
92	      'extension/event-extractors/registry.js': '',
93	      'extension/event-extractors/helpers/dates.js': '',
94	      'extension/event-extractors/load-order.generated.json': '',
95	    }),
96	  );
97	  assert.deepEqual(findings, []);
98	});
99	
100	// npm-test-glob-coverage reads package.json's `test` (and `test:e2e`) scripts, so its
101	// fixtures pair a file list with a scripts object — the real shape of both scripts,
102	// quoted globs included.
103	const globCtx = (files, scripts) =>
104	  ctx({ files, pkg: { scripts } });
105	
106	const SCRIPTS = {
107	  test: 'node --disable-warning=X --test "extension-test/**/*.test.js" "dev/build/test/**/*.test.js" ".claudinite/local/packs/**/*.test.mjs" "dev/requirements/logic/**/*.test.js" dev/requirements/requirements-coverage.test.js',
108	  'test:e2e': 'node --test "dev/requirements/heavy/**/*.test.js"',
109	};
110	
111	test('npm-test-glob-coverage: fires on a test file no `test` pattern reaches', () => {
112	  const findings = npmTestGlobCoverage.run(
113	    globCtx(
114	      ['extension-test/host-policy.test.js', 'dev/security/csp.test.js'],
115	      SCRIPTS,
116	    ),
117	  );
118	  assert.equal(findings.length, 1);
119	  assert.equal(findings[0].file, 'dev/security/csp.test.js');
120	  assert.match(findings[0].what, /reached by no pattern/);
121	  assert.equal(findings[0].severity, 'blocking');
122	});
123	
124	test('npm-test-glob-coverage: quiet when every pattern shape reaches its files', () => {
125	  const findings = npmTestGlobCoverage.run(
126	    globCtx(
127	      [
128	        'extension-test/host-policy.test.js', // `**/` must match ZERO directories too
129	        'extension-test/events-popup/popup.test.js',
130	        'dev/build/test/load-order-generated.test.js',
131	        '.claudinite/local/packs/gcec/pack.test.mjs', // .mjs counts as a test file
132	        'dev/requirements/logic/product-requirements.test.js',
133	        'dev/requirements/requirements-coverage.test.js', // a literal path, not a glob
134	        'extension/host-policy.js', // not a test file at all
135	      ],
136	      SCRIPTS,
137	    ),
138	  );
139	  assert.deepEqual(findings, []);
140	});
141	
142	test('npm-test-glob-coverage: the heavy e2e suite is exempt via scripts["test:e2e"]', () => {
143	  const heavy = 'dev/requirements/heavy/extension-load.chrome.test.js';
144	  assert.deepEqual(npmTestGlobCoverage.run(globCtx([heavy], SCRIPTS)), []);
145	  // …and only because test:e2e declares it: drop that script and the carve-out goes.
146	  const findings = npmTestGlobCoverage.run(globCtx([heavy], { test: SCRIPTS.test }));
147	  assert.equal(findings.length, 1);
148	  assert.equal(findings[0].file, heavy);
149	});
150	
151	test('npm-test-glob-coverage: quiet when the test script is not a `node --test` runner', () => {
152	  const findings = npmTestGlobCoverage.run(
153	    globCtx(['dev/security/csp.test.js'], { test: 'jest' }),
154	  );
155	  assert.deepEqual(findings, []);
156	});
157

1	import { finding } from '../../engine/checks/helpers/findings.mjs';
2	import { wikiPages, hasSection } from './lib.mjs';
3	
4	// Every wiki page carries its reader header and the growth machinery as
5	// top-level sections. `##` is
6	// the contract (a `###` heading deliberately misses); hasSection tolerates
7	// case variation and suffix words ("## Open questions (for the next growth
8	// pass)") and ignores headings inside code fences — an embedded template must
9	// not satisfy the requirement. A non-wiki README inside wiki space (an assets
10	// folder) firing here is by design — assets belong under product-wiki/sample-data/;
11	// a genuine exception uses a reasoned accept.
12	const SECTIONS = ['Key insights', 'Sources', 'Growth log', 'Open questions'];
13	
14	const rule = {
15	  id: 'product-wiki-page-sections',
16	  severity: 'blocking',
17	  doc: 'packs/product-wiki/README.md',
18	  description: 'Every wiki page carries Key insights, Sources, Growth log, and Open questions sections',
19	  why: "the sections are the page's reader header plus the wiki's audit trail and backlog — without them compile-once/refine-in-place degrades to unsourced, unreviewable rewrites nobody can read at a glance",
20	
21	  run(ctx) {
22	    const out = [];
23	    for (const page of wikiPages(ctx.files)) {
24	      const text = ctx.read(page);
25	      if (text === null) continue;
26	      for (const name of SECTIONS) {
27	        if (!hasSection(text, name)) {
28	          out.push(finding(rule, {
29	            file: page,
30	            what: `wiki page is missing its "## ${name}" section`,
31	            fix: 'add it — every wiki page opens with the Key insights header, then carries the growth machinery: the citations list, the dated growth log, and the open-questions backlog (an empty "## Open questions" is valid)',
32	          }));
33	        }
34	      }
35	    }
36	    return out;
37	  },
38	};
39	
40	export default rule;
